  1	﻿function Test-MtCaEmergencyAccessExists {
  2	    <#
  3	    .Synopsis
  4	    Checks if the tenant has at least one emergency/break glass account or account group excluded from all Conditional Access policies
  5	
  6	    .Description
  7	    It is recommended to have at least one emergency/break glass account or account group excluded from all Conditional Access policies.
  8	    This allows for emergency access to the tenant in case of a misconfiguration or other issues.
  9	
 10	    Learn more:
 11	    https://learn.microsoft.com/entra/identity/role-based-access-control/security-emergency-access
 12	
 13	    .Example
 14	    Test-MtCaEmergencyAccessExists
 15	
 16	    .LINK
 17	    https://maester.dev/docs/commands/Test-MtCaEmergencyAccessExists
 18	    #>
 19	    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseSingularNouns', '', Justification = 'Exists is not a plural.')]
 20	    [MaesterTest(
 21	        Id = 'MT.1005',
 22	        Title = 'All Conditional Access policies are configured to exclude at least one emergency/break glass account or group.',
 23	        Product = 'entra',
 24	        Feature = 'conditional-access',
 25	        Area = 'privileged-access',
 26	        ResourceType = 'ConditionalAccessPolicy',
 27	        Severity = 'High',
 28	        UserImpact = 'Low',
 29	        ImplementationCost = 'Low',
 30	        Mitre = 'None',
 31	        Step = 'entra.emergency-access-excluded',
 32	        Service = 'Graph',
 33	        License = 'AAD_PREMIUM',
 34	        Author = 'f-bader',
 35	        Contributor = ('merill', 'thomas-s-schmidt', 'SamErde', 'bubbletroubles')
 36	    )]
 37	    [CmdletBinding()]
 38	    [OutputType([bool])]
 39	    param ()
 40	
 41	    $EmergencyAccessAccounts = Get-MtSetting -Name 'EmergencyAccessAccounts'
 42	
 43	    # Only check policies that are not related to authentication context (the state of policy does not have to be enabled)
 44	    $policies = Get-MtConditionalAccessPolicy | Where-Object { -not $_.conditions.applications.includeAuthenticationContextClassReferences }
 45	
 46	    # Remove policies that are scoped to service principals or agent identities
 47	    $policies = $policies | Where-Object {
 48	        -not $_.conditions.clientApplications.includeServicePrincipals -and
 49	        -not $_.conditions.clientApplications.includeAgentIdServicePrincipals
 50	    }
 51	
 52	    $result = $false
 53	    $PolicyCount = $policies | Measure-Object | Select-Object -ExpandProperty Count
 54	    if (-not $EmergencyAccessAccounts -or $EmergencyAccessAccounts.Count -eq 0) {
 55	        Write-Verbose "No emergency access accounts or groups defined in the Maester config. Use the default logic to detect emergency access accounts or groups."
 56	        $ExcludedUserObjectGUID = $policies.conditions.users.excludeUsers | Group-Object -NoElement | Sort-Object -Property Count -Descending | Select-Object -First 1 -ExpandProperty Name
 57	        $ExcludedUsers = $policies.conditions.users.excludeUsers | Group-Object -NoElement | Sort-Object -Property Count -Descending | Select-Object -First 1 | Select-Object -ExpandProperty Count
 58	        $ExcludedGroupObjectGUID = $policies.conditions.users.excludeGroups | Group-Object -NoElement | Sort-Object -Property Count -Descending | Select-Object -First 1 -ExpandProperty Name
 59	        $ExcludedGroups = $policies.conditions.users.excludeGroups | Group-Object -NoElement | Sort-Object -Property Count -Descending | Select-Object -First 1 | Select-Object -ExpandProperty Count
 60	
 61	        # If the number of enabled policies is not the same as the number of excluded users or groups, there is no emergency access
 62	        if ($PolicyCount -eq $ExcludedUsers -or $PolicyCount -eq $ExcludedGroups) {
 63	            $result = $true
 64	        } else {
 65	            # If the number of excluded users is higher than the number of excluded groups, check the user object GUID
 66	            $CheckId = $ExcludedGroupObjectGUID
 67	            $EmergencyAccessUUIDType = 'group'
 68	            if ($ExcludedUsers -gt $ExcludedGroups) {
 69	                $EmergencyAccessUUIDType = 'user'
 70	                $CheckId = $ExcludedUserObjectGUID
 71	            }
 72	
 73	            # Get displayName of the emergency access account or group
 74	            if ($CheckId) {
 75	                if ($EmergencyAccessUUIDType -eq 'user') {
 76	                    $DisplayName = Invoke-MtGraphRequest -RelativeUri "users/$CheckId" -Select displayName | Select-Object -ExpandProperty displayName
 77	                } else {
 78	                    $DisplayName = Invoke-MtGraphRequest -RelativeUri "groups/$CheckId" -Select displayName | Select-Object -ExpandProperty displayName
 79	                }
 80	
 81	                Write-Verbose "Emergency access account or group: $CheckId"
 82	                $testResult = "Automatically detected emergency access`n`n* $($EmergencyAccessUUIDType): $DisplayName ($CheckId)`n`n"
 83	            }
 84	
 85	            $policiesWithoutEmergency = $policies | Where-Object { $CheckId -notin $_.conditions.users.excludeUsers -and $CheckId -notin $_.conditions.users.excludeGroups }
 86	            $policiesWithoutEmergency | Select-Object -ExpandProperty displayName | Sort-Object | ForEach-Object {
 87	                Write-Verbose "Conditional Access policy $_ does not exclude emergency access $EmergencyAccessUUIDType"
 88	            }
 89	        }
 90	
 91	        $testResult += "These Conditional Access policies don't have the emergency access $EmergencyAccessUUIDType excluded:`n`n%TestResult%"
 92	        Add-MtTestResultDetail -GraphObjects $policiesWithoutEmergency -GraphObjectType ConditionalAccess -Result $testResult
 93	        return $result
 94	
 95	    } else {
 96	        # Resolve emergency access accounts/groups to object IDs and get display names
 97	        $ResolvedEmergencyAccessAccounts = @()
 98	        foreach ($account in $EmergencyAccessAccounts) {
 99	            # Use either Id or UserPrincipalName to identify the account / group and UserPrincipalName as fallback
100	            $identifier = if ($account.Id) { $account.Id } else { $account.UserPrincipalName }
101	            # Determine the type (user or group) while defaulting to 'user'
102	            $type = if ($account.Type) { $account.Type.ToLower() } else { 'user' }
103	
104	            if ($identifier -match '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$') {
105	                # It's an object ID
106	                try {
107	                    $endpoint = if ($type -eq 'group') { "groups/$identifier" } else { "users/$identifier" }
108	                    $object = Invoke-MtGraphRequest -RelativeUri $endpoint -Select id, displayName -ErrorAction Stop
109	                    if ($object) {
110	                        Write-Verbose "Emergency access $type`: $($object.displayName) ($identifier)"
111	                        $ResolvedEmergencyAccessAccounts += @{ObjectId = $object.id; displayName = $object.displayName; type = $type }
112	                    } else {
113	                        Write-Warning "Could not resolve emergency access $type ID: $identifier"
114	                    }
115	                } catch {
116	                    Write-Warning "Could not resolve emergency access $type ID: $identifier. Error: $_"
117	                }
118	            } elseif ($identifier -match '^[^@]+@[^@]+\.[^@]+$') {
119	                # It's a UPN - could be user or group
120	                try {
121	                    $endpoint = if ($type -eq 'group') { "groups" } else { "users/$identifier" }
122	                    if ($type -eq 'group') {
123	                        # For groups, we need to filter by mail or mailNickname
124	                        $object = Invoke-MtGraphRequest -RelativeUri $endpoint -Filter "mail eq '$identifier' or mailNickname eq '$identifier'" -ErrorAction Stop | Select-Object -First 1
125	                    } else {
126	                        $object = Invoke-MtGraphRequest -RelativeUri $endpoint -Select id, displayName -ErrorAction Stop
127	                    }
128	                    if ($object) {
129	                        Write-Verbose "Emergency access $type`: $($object.displayName) ($($object.id))"
130	                        $ResolvedEmergencyAccessAccounts += @{ObjectId = $object.id; displayName = $object.displayName; type = $type }
131	                    } else {
132	                        Write-Warning "Could not resolve emergency access $type`: $identifier"
133	                    }
134	                } catch {
135	                    Write-Warning "Could not resolve emergency access $type`: $identifier. Error: $_"
136	                }
137	            } else {
138	                Write-Warning "Invalid identifier format for emergency access account: $identifier"
139	            }
140	        }
141	        Write-Verbose "Emergency access accounts or groups defined in the Maester config: $($EmergencyAccessAccounts.Count) entries"
142	        $UniqueResolvedEmergencyAccessAccounts = @()
143	        $ResolvedEmergencyAccessAccountKeys = @{}
144	        foreach ($account in $ResolvedEmergencyAccessAccounts) {
145	            $accountKey = "$($account.type):$($account.ObjectId)"
146	            if (-not $ResolvedEmergencyAccessAccountKeys.ContainsKey($accountKey)) {
147	                $ResolvedEmergencyAccessAccountKeys[$accountKey] = $true
148	                $UniqueResolvedEmergencyAccessAccounts += $account
149	            }
150	        }
151	        $ResolvedEmergencyAccessAccounts = $UniqueResolvedEmergencyAccessAccounts
152	        $ResolvedEmergencyAccessUsers = $ResolvedEmergencyAccessAccounts | Where-Object { $_.type -eq 'user' }
153	        $ResolvedEmergencyAccessGroups = $ResolvedEmergencyAccessAccounts | Where-Object { $_.type -eq 'group' }
154	        $EmergencyAccessAccountsUserCount = @($ResolvedEmergencyAccessUsers).Count
155	        $EmergencyAccessAccountsGroupCount = @($ResolvedEmergencyAccessGroups).Count
156	
157	        if ($EmergencyAccessAccountsUserCount -eq 0 -and $EmergencyAccessAccountsGroupCount -eq 0) {
158	            Add-MtTestResultDetail -Result "Emergency access accounts or groups are configured in maester-config.json, but none could be resolved. Verify the configured Id or UserPrincipalName values."
159	            return $false
160	        }
161	
162	        # Find policies that are missing ANY of the configured emergency access accounts or groups
163	        $policiesWithoutEmergency = $policies | Where-Object {
164	            $CurrentPolicy = $_
165	            $missingEmergency = $false
166	
167	            # Check if all configured emergency users are excluded
168	            if ($EmergencyAccessAccountsUserCount -gt 0) {
169	                $ExcludedKnownUsers = @($CurrentPolicy.conditions.users.excludeUsers | Where-Object { $_ -in $ResolvedEmergencyAccessUsers.ObjectId }).Count
170	                if ($ExcludedKnownUsers -lt $EmergencyAccessAccountsUserCount) {
171	                    $missingEmergency = $true
172	                }
173	            }
174	
175	            # Check if all configured emergency groups are excluded
176	            if ($EmergencyAccessAccountsGroupCount -gt 0) {
177	                $ExcludedKnownGroups = @($CurrentPolicy.conditions.users.excludeGroups | Where-Object { $_ -in $ResolvedEmergencyAccessGroups.ObjectId }).Count
178	                if ($ExcludedKnownGroups -lt $EmergencyAccessAccountsGroupCount) {
179	                    $missingEmergency = $true
180	                }
181	            }
182	
183	            $missingEmergency
184	        }
185	        if ($policiesWithoutEmergency.Count -eq 0) {
186	            $result = $true
187	            $testResult = "All Conditional Access policies exclude the configured emergency access accounts or groups:`n`n"
188	            $ResolvedEmergencyAccessAccounts | ForEach-Object {
189	                $typeLabel = if ($_.type -eq 'group') { 'Group' } else { 'User' }
190	                if ($_.displayName) {
191	                    $testResult += "* $typeLabel`: $($_.displayName) ($($_.ObjectId))`n"
192	                } else {
193	                    $testResult += "* $typeLabel`: $($_.ObjectId)`n"
194	                }
195	            }
196	            Add-MtTestResultDetail -Result $testResult
197	            return $result
198	        } else {
199	            $testResult = "Configured emergency access accounts or groups:`n`n"
200	            $ResolvedEmergencyAccessAccounts | ForEach-Object {
201	                $typeLabel = if ($_.type -eq 'group') { 'Group' } else { 'User' }
202	                if ($_.displayName) {
203	                    $testResult += "* $typeLabel`: $($_.displayName) ($($_.ObjectId))`n"
204	                } else {
205	                    $testResult += "* $typeLabel`: $($_.ObjectId)`n"
206	                }
207	            }
208	            $testResult += "`n`nThese Conditional Access policies don't have the configured emergency access accounts and groups excluded:`n`n%TestResult%"
209	            Add-MtTestResultDetail -GraphObjects $policiesWithoutEmergency -GraphObjectType ConditionalAccess -Result $testResult
210	            return $result
211	        }
212	    }
213	}
