  3	    .SYNOPSIS
  4	    Returns one MT.1034 instance per emergency access account (up to five).
  5	
  6	    .DESCRIPTION
  7	    Instance source of the MT.1034 family. The suffix is the account's position in the list (MT.1034.0 to
  8	    MT.1034.4) and the title names the account, as the Maester 2.x rows did.
  9	    #>
 10	    [CmdletBinding()]
 11	    [OutputType([pscustomobject])]
 12	    param()
 13	
 14	    $emergencyAccessUsers = @(Get-MtUser -Count 5 -UserType 'EmergencyAccess' | Where-Object { $_ })
 15	    for ($i = 0; $i -lt $emergencyAccessUsers.Count; $i++) {
 16	        $user = $emergencyAccessUsers[$i]
 17	        [pscustomobject]@{
 18	            Id    = [string]$i
 19	            Title = "Emergency access users should not be blocked ($($user.userPrincipalName))"
 20	            Data  = $user
 21	        }
 22	    }
 23	}
