 25	function Test-MtCaWhatIfEmergencyAccessNotBlocked {
 26	    <#
 27	    .SYNOPSIS
 28	    Checks with the Conditional Access What If API that no Conditional Access policy applies to an emergency access account.
 29	
 30	    .DESCRIPTION
 31	    Runs once per emergency access account returned by the instance source and evaluates an Exchange
 32	    ActiveSync sign-in to Office 365 Exchange Online for that account. Passes when no policy applies.
 33	
 34	    .LINK
 35	    https://maester.dev/docs/tests/MT.1034
 36	    #>
 37	    [MaesterTest(
 38	        Id = 'MT.1034',
 39	        Title = 'Emergency access users should not be blocked.',
 40	        Product = 'entra',
 41	        Feature = 'conditional-access',
 42	        Area = 'privileged-access',
 43	        ResourceType = 'User',
 44	        Severity = 'High',
 45	        UserImpact = 'Low',
 46	        ImplementationCost = 'Low',
 47	        Mitre = 'None',
 48	        Step = 'entra.emergency-access-excluded',
 49	        Service = 'Graph',
 50	        License = 'AAD_PREMIUM',
 51	        LongRunning,
 52	        InstanceSource = 'Get-MtCaWhatIfEmergencyAccessInstance',
 53	        Author = 'merill',
 54	        Contributor = ('f-bader', 'milanschwartz', 'jasperbaes')
 55	    )]
 56	    [CmdletBinding()]
 57	    [OutputType([bool])]
 58	    param(
 59	        # The emergency access account to evaluate, supplied by the engine.
 60	        $Instance
 61	    )
 62	
 63	    $policies = @(Test-MtConditionalAccessWhatIf -UserId $Instance.Data.id -IncludeApplications '00000002-0000-0ff1-ce00-000000000000' -ClientAppType exchangeActiveSync | Where-Object { $_ })
 64	    if ($policies.Count -eq 0) {
 65	        Add-MtTestResultDetail -Result "Well done. No Conditional Access policy applies to $($Instance.Data.userPrincipalName)."
 66	        return $true
 67	    }
 68	    Add-MtTestResultDetail -Result "These Conditional Access policies apply to $($Instance.Data.userPrincipalName):`n`n%TestResult%" -GraphObjects $policies -GraphObjectType ConditionalAccess
 69	    return $false
 70	}

